package io.tornado.optimization;
import io.tornado.persistence.Direction;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class WalkForwardProfileSelectorTest{private final WalkForwardProfileSelector selector=new WalkForwardProfileSelector();
 @Test void minimumSamplesAndWilsonRejectTinyPerfectCandidate(){var tiny=new WalkForwardProfileSelector.Configuration("1m","tiny");var robust=new WalkForwardProfileSelector.Configuration("5m","robust");var ranked=selector.rank(new LinkedHashMap<>(Map.of(tiny,observations(20,i->true),robust,observations(600,i->i%10<7))),100,.1);assertThat(ranked.stream().filter(x->x.configuration().equals(tiny)).findFirst().orElseThrow().eligible()).isFalse();var accepted=ranked.stream().filter(x->x.configuration().equals(robust)).findFirst().orElseThrow();assertThat(accepted.eligible()).isTrue();assertThat(accepted.evidence().wilsonDirectionalScore()).isLessThan(accepted.evidence().directionalAccuracy());}
 @Test void finalTestOutcomesNeverInfluenceCandidateSelectionScore(){var config=new WalkForwardProfileSelector.Configuration("15m","20");List<WalkForwardProfileSelector.Observation>goodTest=observations(600,i->i<480?i%10<7:true);List<WalkForwardProfileSelector.Observation>badTest=observations(600,i->i<480?i%10<7:false);var a=selector.evaluate(config,goodTest,100,.1);var b=selector.evaluate(config,badTest,100,.1);assertThat(a.selectionScore()).isEqualTo(b.selectionScore());assertThat(a.evidence().directionalAccuracy()).isGreaterThan(b.evidence().directionalAccuracy());assertThat(a.testFrom()).isEqualTo(b.testFrom());}
 @Test void walkForwardConsistencyRewardsRepeatablePositiveWindows(){var stable=new WalkForwardProfileSelector.Configuration("30m","14");var unstable=new WalkForwardProfileSelector.Configuration("1h","14");List<WalkForwardProfileSelector.Observation>a=observations(600,i->i%10<7);List<WalkForwardProfileSelector.Observation>b=observations(600,i->i<360||i>=480);var ranked=selector.rank(new LinkedHashMap<>(Map.of(stable,a,unstable,b)),100,.1);assertThat(ranked.getFirst().configuration()).isEqualTo(stable);assertThat(ranked.getFirst().evidence().walkForwardPositiveWindows()).isEqualTo(ranked.getFirst().evidence().walkForwardWindows());}
 private List<WalkForwardProfileSelector.Observation>observations(int count,java.util.function.IntPredicate success){Instant base=Instant.parse("2024-01-01T00:00:00Z");List<WalkForwardProfileSelector.Observation>rows=new ArrayList<>();for(int i=0;i<count;i++){Instant at=base.plusSeconds(i*900L);rows.add(new WalkForwardProfileSelector.Observation(1,at,at,at.plusSeconds(900),Direction.UP,new BigDecimal("100"),success.test(i)?new BigDecimal("101"):new BigDecimal("99")));}return rows;}}
